alt='''def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); comps=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=2 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop(); cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(x+dx,y+dy)
     if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]]==2 and z not in seen: seen.add(z); q.append(z)
   comps.append(cells)
 out=[[0]*6 for _ in range(3)]
 for i,cells in enumerate(comps):
  rows={x:sum(xx==x for xx,yy in cells) for x,yy in cells}; base=max(rows,key=rows.get); val=1 if any(x<base for x,yy in cells) else 3
  r=0 if i<3 else 2; c=[0,2,3,5,0,2,3][i]; out[r][c]=val
 return out
'''
